insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-135', 'tec', null, 'No transporte de vacinas em caixa térmica, a temperatura interna deve ser mantida entre:', '["+2 °C e +8 °C, monitorada com termômetro.","-10 °C e 0 °C.","+10 °C e +20 °C.","0 °C e +2 °C.","não precisa de controle."]'::jsonb, 0, 'As bobinas reutilizáveis devem ser ambientadas antes do uso para não congelar as vacinas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-136', 'tec', null, 'Na avaliação primária do trauma (protocolo XABCDE), a letra X refere-se ao controle de:', '["hemorragia exsanguinante.","via aérea.","exposição do paciente.","estado neurológico.","circulação cerebral."]'::jsonb, 0, 'O sangramento externo grave mata mais rápido e deve ser controlado antes mesmo da via aérea.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-137', 'tec', null, 'No atendimento ao trauma, a letra A da avaliação primária corresponde a:', '["vias aéreas com proteção da coluna cervical.","avaliação da dor.","administração de analgésico.","acesso venoso.","aferição da pressão arterial."]'::jsonb, 0, 'A: via aérea + estabilização cervical; B: respiração; C: circulação; D: neurológico; E: exposição.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-138', 'tec', null, 'Adulto consciente com obstrução grave de vias aéreas por corpo estranho (não consegue falar nem tossir). A conduta recomendada é:', '["realizar compressões abdominais (manobra de Heimlich).","oferecer água para empurrar o objeto.","realizar varredura digital às cegas.","deitá-lo e iniciar ventilações imediatamente.","aguardar que ele tussa sozinho."]'::jsonb, 0, 'Se a vítima ficar inconsciente, inicia-se a RCP. Em gestantes e obesos, compressões torácicas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-139', 'tec', null, 'Na RCP de lactente realizada por dois socorristas profissionais, a relação compressão-ventilação recomendada é:', '["15:2.","30:2.","5:1.","3:1.","30:1."]'::jsonb, 0, 'Com um socorrista, 30:2. Em crianças e lactentes com dois socorristas, 15:2.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-140', 'tec', null, 'No uso do desfibrilador externo automático (DEA) em adulto, as pás devem ser posicionadas:', '["uma abaixo da clavícula direita e outra na lateral do tórax, abaixo do mamilo esquerdo.","ambas sobre o esterno.","nas costas, lado a lado.","sobre o abdome.","uma em cada braço."]'::jsonb, 0, 'Posição anterolateral. Deve-se secar o tórax e não tocar o paciente durante a análise e o choque.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-141', 'tec', null, 'Na hemorragia externa grave em membro, a primeira medida é:', '["compressão direta sobre o ferimento; se não houver controle, usar torniquete.","elevar o membro e aguardar.","aplicar gelo diretamente no ferimento.","lavar com água para visualizar a lesão.","oferecer líquidos à vítima."]'::jsonb, 0, 'O torniquete deve ter o horário de aplicação anotado.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-142', 'tec', null, 'Na imobilização de uma fratura de membro, deve-se:', '["imobilizar a articulação acima e a abaixo da fratura.","tentar recolocar o osso no lugar.","imobilizar apenas o local da fratura.","massagear o membro antes de imobilizar.","manter o membro em movimento para evitar rigidez."]'::jsonb, 0, 'Verificar pulso, perfusão e sensibilidade distais antes e depois da imobilização.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-143', 'tec', null, 'No primeiro atendimento a uma queimadura térmica pequena, recomenda-se:', '["resfriar com água corrente em temperatura ambiente e não aplicar gelo, pasta de dente ou manteiga.","aplicar gelo diretamente sobre a pele.","romper as bolhas para aliviar a dor.","passar pasta de dente ou manteiga.","cobrir com algodão."]'::jsonb, 0, 'O gelo pode aprofundar a lesão; substâncias caseiras aumentam o risco de infecção.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-144', 'tec', null, 'A queimadura que acomete a epiderme e parte da derme, com formação de bolhas (flictenas) e dor intensa, é de:', '["segundo grau.","primeiro grau.","terceiro grau.","quarto grau.","grau zero."]'::jsonb, 0, '1º grau: apenas eritema. 3º grau: espessura total, pele esbranquiçada ou carbonizada, pouco dolorosa.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-145', 'tec', null, 'São sinais de choque hipovolêmico:', '["taquicardia, hipotensão, pele fria e pegajosa e enchimento capilar lento.","bradicardia, hipertensão e pele quente.","pele rosada e seca, com pulso cheio.","aumento da diurese e febre.","hipertensão e rubor facial."]'::jsonb, 0, 'Há também agitação ou rebaixamento do nível de consciência e oligúria.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-146', 'tec', null, 'Durante uma crise convulsiva tônico-clônica, a conduta correta é:', '["proteger a cabeça, afastar objetos e lateralizar o paciente, sem introduzir nada na boca.","segurar os membros com força.","colocar um objeto entre os dentes.","oferecer água durante a crise.","jogar água fria no rosto."]'::jsonb, 0, 'Registrar a duração; crises com mais de 5 minutos exigem atendimento de urgência.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-147', 'tec', null, 'A Escala Pré-hospitalar de Cincinnati, usada na suspeita de AVC, avalia:', '["queda facial, fraqueza nos braços e alteração da fala.","pressão arterial, pulso e temperatura.","abertura ocular, resposta verbal e motora.","glicemia, pupilas e diurese.","dor, sono e apetite."]'::jsonb, 0, 'Qualquer alteração indica alta probabilidade de AVC: anotar o horário de início dos sintomas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-148', 'tec', null, 'O sintoma típico do infarto agudo do miocárdio é:', '["dor torácica em aperto, que pode irradiar para o braço esquerdo, a mandíbula ou o dorso, por mais de 20 minutos.","dor em pontada que piora com a palpação.","dor abdominal que melhora com a alimentação.","cefaleia com rigidez de nuca.","prurido generalizado."]'::jsonb, 0, 'Idosos, mulheres e diabéticos podem ter sintomas atípicos (dispneia, náusea, mal-estar).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-149', 'tec', null, 'Na intoxicação por ingestão de produtos cáusticos (soda cáustica, por exemplo), é correto:', '["não provocar vômito.","provocar vômito imediatamente.","oferecer leite em grande quantidade para neutralizar.","dar vinagre para neutralizar.","administrar carvão ativado em todos os casos."]'::jsonb, 0, 'O vômito expõe novamente o esôfago ao cáustico. Contato: CIATox / Disque-Intoxicação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-150', 'tec', null, 'No atendimento inicial a vítima de acidente ofídico (picada de cobra), deve-se:', '["manter a vítima em repouso, com o membro elevado, e levá-la rapidamente para receber soro, sem garrotear, cortar ou sugar o local.","fazer torniquete acima da picada.","cortar o local e sugar o veneno.","aplicar álcool ou querosene no local.","oferecer bebida alcoólica para aliviar a dor."]'::jsonb, 0, 'O único tratamento específico é o soro antiofídico.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-151', 'tec', null, 'No Protocolo de Manchester, o paciente classificado com a cor vermelha deve ser atendido:', '["imediatamente (emergência).","em até 60 minutos.","em até 120 minutos.","em até 240 minutos.","no dia seguinte."]'::jsonb, 0, 'Vermelho: emergência, atendimento imediato; laranja: muito urgente, até 10 min.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-152', 'tec', null, 'No centro cirúrgico, é atribuição do circulante de sala:', '["abrir os materiais estéreis para a equipe, auxiliar no posicionamento do paciente e participar da contagem de compressas.","realizar a incisão cirúrgica.","permanecer paramentado no campo operatório entregando instrumentais.","prescrever a anestesia.","realizar a sutura da pele."]'::jsonb, 0, 'O circulante não se paramenta; o instrumentador atua no campo estéril.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-153', 'tec', null, 'A Lista de Verificação de Segurança Cirúrgica da OMS é aplicada em três momentos:', '["antes da indução anestésica, antes da incisão cirúrgica e antes de o paciente sair da sala de operação.","na admissão, na alta e no retorno ambulatorial.","antes do jejum, durante a cirurgia e na UTI.","apenas após a cirurgia.","no pré-operatório mediato, apenas."]'::jsonb, 0, 'Sign in, time out e sign out.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-154', 'tec', null, 'Na sala de recuperação pós-anestésica, a escala utilizada para avaliar as condições de alta do paciente é a de:', '["Aldrete e Kroulik.","Braden.","Morse.","Apgar.","Katz."]'::jsonb, 0, 'Avalia atividade, respiração, circulação, consciência e saturação/coloração.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-155', 'tec', null, 'A posição de litotomia é indicada principalmente para:', '["cirurgias e procedimentos ginecológicos, urológicos e perineais.","cirurgias da coluna vertebral.","cirurgias cardíacas.","neurocirurgias da fossa posterior.","cirurgias de tireoide."]'::jsonb, 0, 'O paciente fica em decúbito dorsal, com pernas elevadas em perneiras; cuidado com a compressão de nervos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-156', 'tec', null, 'A placa dispersiva (neutra) do bisturi elétrico deve ser colocada:', '["em área muscular, bem vascularizada, limpa, seca, sem pelos e longe de proeminências ósseas e próteses metálicas.","sobre proeminências ósseas.","em área com pelos e úmida.","sobre cicatrizes antigas.","em qualquer local, sem critério."]'::jsonb, 0, 'Contato inadequado pode causar queimaduras.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-157', 'tec', null, 'Quando a tricotomia é necessária no pré-operatório, recomenda-se realizá-la:', '["imediatamente antes da cirurgia (até 2 horas), com tricotomizador elétrico.","na véspera, com lâmina de barbear.","uma semana antes, com cera.","sempre, em todo o corpo.","com lâmina, logo após o banho, no dia anterior."]'::jsonb, 0, 'Lâminas causam microlesões que aumentam o risco de infecção do sítio cirúrgico.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-158', 'tec', null, 'Na degermação cirúrgica das mãos e antebraços, as mãos devem ser mantidas:', '["acima do nível dos cotovelos, para que a água escorra das mãos para os cotovelos.","abaixo dos cotovelos.","em contato com a pia.","secas antes da escovação.","com adornos, desde que limpos."]'::jsonb, 0, 'O sentido é sempre da área mais limpa (mãos) para a menos limpa (cotovelos).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-159', 'tec', null, 'A sequência correta do processamento de produtos para saúde na CME é:', '["recepção e limpeza, preparo e acondicionamento, esterilização, armazenamento e distribuição.","esterilização, limpeza, preparo e distribuição.","armazenamento, limpeza e esterilização.","preparo, esterilização e limpeza.","distribuição, preparo, limpeza e esterilização."]'::jsonb, 0, 'A limpeza é a etapa essencial: sem ela não há esterilização eficaz.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-160', 'tec', null, 'A fita zebrada (indicador químico externo) colocada nos pacotes autoclavados indica que:', '["o pacote passou pelo processo de esterilização, mas não garante a esterilidade.","o material está estéril, dispensando outros controles.","o material foi lavado corretamente.","o pacote pode ser usado por tempo indeterminado.","o pacote está contaminado."]'::jsonb, 0, 'É indicador de processo (classe 1). A eficácia é confirmada por indicadores internos e biológicos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-161', 'tec', null, 'Segundo a RDC nº 15/2012, para a esterilização de produtos para saúde:', '["não é permitido o uso de estufas (calor seco).","a estufa é o método preferencial.","a fervura em água é método de esterilização aceito.","o álcool 70% esteriliza os instrumentais.","basta a limpeza manual."]'::jsonb, 0, 'A RDC 15/2012 veda as estufas para esterilização; o método mais usado é o vapor saturado sob pressão.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-162', 'tec', null, 'No pós-operatório, a deambulação precoce, quando liberada, tem como principal benefício:', '["prevenir trombose venosa profunda e complicações respiratórias.","aumentar a dor na ferida.","atrasar o retorno da função intestinal.","causar deiscência obrigatoriamente.","substituir a analgesia."]'::jsonb, 0, 'Também favorece o retorno do peristaltismo e da função vesical.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-163', 'tec', null, 'O período do parto que vai da dilatação completa até a expulsão do feto é chamado de:', '["período expulsivo (2º período).","dilatação (1º período).","dequitação (3º período).","Greenberg (4º período).","pré-parto."]'::jsonb, 0, '1º: dilatação; 2º: expulsão; 3º: dequitação (saída da placenta); 4º: Greenberg (1ª hora após a dequitação).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-164', 'tec', null, 'A dequitação corresponde:', '["à saída da placenta e das membranas.","à dilatação do colo do útero.","ao nascimento do bebê.","à primeira mamada.","ao corte do cordão umbilical."]'::jsonb, 0, 'É o 3º período do parto.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-165', 'tec', null, 'Para o recém-nascido a termo com boa vitalidade, recomenda-se o clampeamento do cordão umbilical:', '["após 1 a 3 minutos do nascimento.","imediatamente, em todos os casos.","após 30 minutos.","somente após a dequitação.","após o primeiro banho."]'::jsonb, 0, 'O clampeamento tardio aumenta as reservas de ferro do bebê.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-166', 'tec', null, 'As boas práticas de atenção ao recém-nascido saudável na primeira hora de vida incluem:', '["contato pele a pele imediato e início da amamentação.","banho imediato e separação da mãe.","aspiração rotineira de vias aéreas em todos os RN.","oferta de glicose oral.","manter o RN em berço aquecido longe da mãe."]'::jsonb, 0, 'O contato pele a pele também previne hipotermia e favorece o vínculo.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-167', 'tec', null, 'A vitamina K administrada ao recém-nascido logo após o nascimento tem a finalidade de prevenir:', '["a doença hemorrágica do recém-nascido.","a icterícia.","a conjuntivite neonatal.","a hipoglicemia.","a tuberculose."]'::jsonb, 0, 'Dose habitual de 1 mg por via intramuscular.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-168', 'tec', null, 'São sinais de pega correta na amamentação:', '["boca bem aberta, lábio inferior virado para fora, queixo tocando a mama e mais aréola visível acima da boca do que abaixo.","boca pouco aberta abocanhando só o mamilo.","bochechas encovadas durante a sucção.","ruídos de estalo a cada sucção.","lábios voltados para dentro."]'::jsonb, 0, 'Pega incorreta causa fissuras mamilares e baixa transferência de leite.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-169', 'tec', null, 'No ingurgitamento mamário, a orientação adequada é:', '["manter as mamadas frequentes, em livre demanda, e realizar ordenha manual da aréola antes da mamada, se necessário.","suspender a amamentação até melhorar.","enfaixar as mamas.","oferecer mamadeira ao bebê.","aplicar calor intenso por várias horas."]'::jsonb, 0, 'Esvaziar a mama é o principal tratamento; amolecer a aréola facilita a pega.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-170', 'tec', null, 'A icterícia que surge nas primeiras 24 horas de vida do recém-nascido:', '["é considerada patológica e deve ser investigada.","é sempre fisiológica.","não exige avaliação.","é tratada apenas com banho de sol.","indica que o bebê está bem alimentado."]'::jsonb, 0, 'A icterícia fisiológica surge após 24 horas de vida.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-171', 'tec', null, 'Quanto aos cuidados com o coto umbilical, é correto orientar:', '["mantê-lo limpo e seco, sem faixas, moedas ou substâncias caseiras.","cobri-lo com faixa apertada.","aplicar pó de café para secar.","retirá-lo manualmente no 3º dia.","colocar moeda para evitar hérnia."]'::jsonb, 0, 'A queda ocorre em geral entre o 7º e o 15º dia. Vermelhidão, odor ou secreção indicam infecção.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-172', 'tec', null, 'Os valores de referência de frequência cardíaca e frequência respiratória do recém-nascido em repouso são, respectivamente:', '["120 a 160 bpm e 40 a 60 irpm.","60 a 100 bpm e 12 a 20 irpm.","80 a 100 bpm e 20 a 30 irpm.","160 a 200 bpm e 60 a 80 irpm.","100 a 120 bpm e 10 a 20 irpm."]'::jsonb, 0, 'Valores de adulto (60–100 bpm; 12–20 irpm) não se aplicam ao RN.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-173', 'tec', null, 'O teste do coraçãozinho (oximetria de pulso) no recém-nascido é realizado:', '["entre 24 e 48 horas de vida, no membro superior direito e em um dos membros inferiores.","no primeiro minuto de vida.","aos 30 dias de vida.","apenas em RN prematuros.","no lóbulo da orelha, aos 6 meses."]'::jsonb, 0, 'Triagem para cardiopatias congênitas críticas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-174', 'tec', null, 'São sinais de alerta na gestação que exigem procura imediata do serviço de saúde:', '["sangramento vaginal, perda de líquido, cefaleia intensa com visão turva e diminuição dos movimentos fetais.","aumento do apetite e da frequência urinária.","náusea matinal no primeiro trimestre.","aumento das mamas.","cansaço leve."]'::jsonb, 0, 'Cefaleia com escotomas e edema súbito podem indicar pré-eclâmpsia.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-175', 'tec', null, 'A vacina influenza na gestação:', '["é recomendada e pode ser aplicada em qualquer idade gestacional.","é contraindicada no primeiro trimestre.","só pode ser aplicada após o parto.","exige autorização judicial.","é feita com vírus vivo."]'::jsonb, 0, 'Gestantes e puérperas são grupo prioritário pelo maior risco de complicações.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-176', 'tec', null, 'Logo após a dequitação, o útero contraído, palpável na altura da cicatriz umbilical, constitui:', '["o globo de segurança de Pinard.","uma atonia uterina.","um sinal de infecção puerperal.","uma hemorragia oculta.","o sinal de Chadwick."]'::jsonb, 0, 'Útero amolecido e aumentado sugere atonia, principal causa de hemorragia pós-parto.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-177', 'tec', null, 'São sinais de desidratação na criança:', '["olhos fundos, sede intensa, sinal da prega que desaparece lentamente e boca seca.","olhos brilhantes e diurese abundante.","fontanela abaulada e ganho de peso.","pele úmida e lágrimas abundantes.","aumento do apetite."]'::jsonb, 0, 'Letargia e incapacidade de beber indicam desidratação grave.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-178', 'tec', null, 'Segundo a Lei nº 10.216/2001, o tratamento da pessoa com transtorno mental:', '["deve ser feito preferencialmente em serviços comunitários de saúde mental.","deve ser feito preferencialmente em hospitais psiquiátricos.","exige internação em todos os casos.","dispensa o consentimento da família e do paciente sempre.","deve visar ao isolamento social."]'::jsonb, 0, 'A lei redireciona o modelo assistencial; a internação só é indicada quando recursos extra-hospitalares forem insuficientes.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-179', 'tec', null, 'Diante de um paciente que relata pensamentos de suicídio, é correto:', '["acolher, ouvir sem julgar, perguntar diretamente sobre a ideação e comunicar a equipe para avaliação e vigilância.","evitar falar sobre o assunto para não induzir o ato.","dizer que ele está exagerando.","prometer manter segredo absoluto.","deixá-lo sozinho para refletir."]'::jsonb, 0, 'Perguntar sobre suicídio não aumenta o risco; objetos perigosos devem ser retirados do alcance.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-180', 'tec', null, 'O delirium tremens, na síndrome de abstinência alcoólica, caracteriza-se por:', '["confusão mental, alucinações, tremores intensos, sudorese e taquicardia, em geral 48 a 72 horas após a última ingestão.","sonolência e bradicardia.","euforia e aumento do apetite.","hipotermia e bradipneia.","ausência de sintomas físicos."]'::jsonb, 0, 'É emergência médica, com risco de convulsões e morte.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-181', 'tec', null, 'Para pacientes em uso de carbonato de lítio, é fundamental:', '["monitorar o nível sérico do lítio e observar sinais de intoxicação, como tremores, vômitos, diarreia e confusão.","suspender a ingestão de água.","administrar junto com diuréticos sem controle.","dispensar exames laboratoriais.","dobrar a dose em caso de vômitos."]'::jsonb, 0, 'O lítio tem janela terapêutica estreita; desidratação aumenta o risco de intoxicação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-182', 'tec', null, 'Segundo a Resolução COFEN nº 427/2012, a contenção mecânica de pacientes:', '["só pode ser feita como último recurso, sob supervisão do enfermeiro e prescrição médica (salvo urgência), com monitoramento e registro, nunca como punição.","pode ser usada como medida disciplinar.","dispensa registro em prontuário.","pode ser mantida por tempo indeterminado sem reavaliação.","pode ser feita por acompanhantes."]'::jsonb, 0, 'Exige monitoramento do nível de consciência, sinais vitais, perfusão e integridade da pele.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-183', 'tec', null, 'Para pessoas com hipertensão arterial, é orientação adequada de mudança no estilo de vida:', '["reduzir o consumo de sal, praticar atividade física regular, controlar o peso e evitar tabaco e excesso de álcool.","suspender a medicação quando a pressão normalizar.","aumentar o consumo de alimentos industrializados.","evitar qualquer atividade física.","usar o remédio apenas quando sentir dor de cabeça."]'::jsonb, 0, 'A hipertensão costuma ser assintomática; o tratamento é contínuo.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-184', 'tec', null, 'Na prevenção do pé diabético, deve-se orientar o paciente a:', '["inspecionar os pés diariamente, secar bem entre os dedos e não andar descalço.","cortar as unhas em formato arredondado e bem rentes.","usar bolsa de água quente para aquecer os pés.","remover calos com lâmina em casa.","usar sapatos apertados para firmar os pés."]'::jsonb, 0, 'A neuropatia reduz a sensibilidade; unhas devem ser cortadas retas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-185', 'tec', null, 'O único método contraceptivo que também protege contra infecções sexualmente transmissíveis é:', '["o preservativo (masculino ou interno/feminino).","o DIU de cobre.","o anticoncepcional oral combinado.","o anticoncepcional injetável trimestral.","a laqueadura tubária."]'::jsonb, 0, 'Daí a orientação de dupla proteção: preservativo + outro método.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-186', 'tec', null, 'Para a coleta do exame citopatológico do colo do útero, a mulher deve ser orientada a:', '["evitar relações sexuais, duchas e cremes vaginais nas 48 horas anteriores e não estar menstruada.","fazer ducha vaginal antes do exame.","comparecer menstruada, de preferência.","usar creme vaginal na véspera.","estar em jejum de 12 horas."]'::jsonb, 0, 'Essas condições evitam interferências na amostra.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-187', 'tec', null, 'Na busca ativa de tuberculose na população geral, considera-se sintomático respiratório a pessoa com:', '["tosse por 3 semanas ou mais, que deve realizar exame de escarro.","tosse há 2 dias.","febre isolada há 1 dia.","coriza e espirros.","dor de garganta há 1 semana."]'::jsonb, 0, 'Em populações vulneráveis (pessoas em situação de rua, privadas de liberdade, PVHIV), qualquer duração de tosse.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-188', 'tec', null, 'O sinal característico da hanseníase é:', '["mancha ou área da pele com alteração de sensibilidade (térmica, dolorosa ou tátil).","febre alta e tosse produtiva.","diarreia crônica.","manchas que coçam muito e desaparecem em horas.","dor de garganta e placas brancas."]'::jsonb, 0, 'Também pode haver espessamento de nervos periféricos com dor, choque ou perda de força.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-189', 'tec', null, 'O vetor responsável pela transmissão da dengue, zika e chikungunya em áreas urbanas é o mosquito:', '["Aedes aegypti.","Anopheles.","Culex.","Lutzomyia.","barbeiro (Triatoma)."]'::jsonb, 0, 'Anopheles: malária; Lutzomyia: leishmaniose; barbeiro: doença de Chagas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-190', 'tec', null, 'Para pacientes com suspeita de dengue, deve-se orientar:', '["hidratação oral abundante e evitar ácido acetilsalicílico e anti-inflamatórios.","uso de ácido acetilsalicílico para a febre.","restrição de líquidos.","uso de anti-inflamatórios para dor muscular.","repouso sem ingestão de líquidos."]'::jsonb, 0, 'AAS e AINEs aumentam o risco de sangramento.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-191', 'tec', null, 'A leptospirose é transmitida principalmente por:', '["contato com água ou lama contaminadas pela urina de roedores, especialmente em enchentes.","picada de mosquito.","via respiratória.","relação sexual.","transfusão de sangue."]'::jsonb, 0, 'Medidas: evitar contato com água de enchente, usar botas e luvas, controlar roedores.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-192', 'tec', null, 'Após mordedura de animal com risco de transmissão da raiva, a primeira medida local é:', '["lavar o ferimento abundantemente com água e sabão.","fazer sutura imediata do ferimento.","aplicar torniquete.","cauterizar com ferro quente.","não lavar o local."]'::jsonb, 0, 'Depois, avaliar a indicação de vacina e/ou soro antirrábico, conforme o animal e o tipo de exposição.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-193', 'tec', null, 'As manchas de Koplik (pequenos pontos brancos na mucosa oral) são características de:', '["sarampo.","rubéola.","varicela.","dengue.","escarlatina."]'::jsonb, 0, 'Surgem antes do exantema maculopapular, que começa na face e desce para o corpo.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-194', 'tec', null, 'Na meningite, são sinais de irritação meníngea:', '["rigidez de nuca e sinais de Kernig e Brudzinski.","sinal de Murphy e Blumberg.","sinal de Homans.","sinal de Chvostek.","sinal de Romberg."]'::jsonb, 0, 'Febre, cefaleia, vômitos em jato e, na meningocócica, petéquias.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-195', 'tec', null, 'O HIV NÃO é transmitido por:', '["abraço, beijo no rosto, compartilhamento de talheres e uso do mesmo banheiro.","relação sexual sem preservativo.","compartilhamento de seringas.","transmissão vertical (gestação, parto e amamentação).","transfusão de sangue contaminado."]'::jsonb, 0, 'Combater o estigma faz parte da educação em saúde.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-196', 'tec', null, 'No diagnóstico da sífilis, o VDRL é um teste:', '["não treponêmico, usado também para acompanhar a resposta ao tratamento.","treponêmico, que nunca negativa.","de imagem.","exclusivo para HIV.","que dispensa confirmação."]'::jsonb, 0, 'Testes treponêmicos (como o teste rápido) costumam permanecer reagentes por toda a vida.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-197', 'tec', null, 'A escabiose (sarna) caracteriza-se por:', '["prurido intenso, que piora à noite, com lesões em dobras como entre os dedos, punhos e axilas.","febre alta e tosse.","manchas sem prurido e sem sensibilidade.","lesões apenas no couro cabeludo.","dor articular intensa."]'::jsonb, 0, 'Causada pelo Sarcoptes scabiei; contactantes devem ser tratados ao mesmo tempo.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-198', 'tec', null, 'A chikungunya diferencia-se clinicamente da dengue principalmente por:', '["artralgia (dor nas articulações) intensa, que pode persistir por meses.","ausência de febre.","sangramentos graves em todos os casos.","transmissão por via respiratória.","lesões de pele com perda de sensibilidade."]'::jsonb, 0, 'Ambas são transmitidas pelo Aedes aegypti.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-199', 'tec', null, 'A notificação compulsória de doenças e agravos é obrigatória:', '["para médicos, outros profissionais de saúde e responsáveis por serviços de saúde, públicos ou privados.","apenas para médicos de hospitais públicos.","apenas após confirmação laboratorial, sempre.","somente quando o paciente autorizar.","apenas para doenças que causem óbito."]'::jsonb, 0, 'Muitos agravos são notificados já na suspeita.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-200', 'tec', null, 'A escala de Morse é utilizada para avaliar:', '["o risco de queda.","o risco de lesão por pressão.","o nível de consciência.","a dor neonatal.","o grau de sedação."]'::jsonb, 0, 'Considera histórico de quedas, diagnóstico secundário, auxílio na deambulação, terapia EV, marcha e estado mental.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-201', 'tec', null, 'Segundo a classificação da OMS adotada pelo Programa Nacional de Segurança do Paciente, evento adverso é:', '["o incidente que resulta em dano ao paciente.","qualquer reclamação do paciente.","o incidente que não atingiu o paciente.","a falha de equipamento sem envolvimento de pacientes.","a reação esperada de um medicamento."]'::jsonb, 0, 'Near miss = incidente que não atingiu o paciente; incidente sem dano = atingiu, mas não causou dano.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-202', 'tec', null, 'Um técnico de enfermagem percebe, antes de administrar, que o medicamento preparado era destinado a outro paciente. Esse incidente é classificado como:', '["near miss (quase erro).","evento adverso grave.","incidente com dano.","erro de prescrição médica.","reação adversa ao medicamento."]'::jsonb, 0, 'O incidente não chegou ao paciente; deve ser notificado para melhoria do processo.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-203', 'tec', null, 'Para garantir a comunicação efetiva em uma prescrição verbal em situação de emergência, recomenda-se:', '["repetir em voz alta o que foi prescrito para confirmação e registrar assim que possível.","executar sem repetir para ganhar tempo.","pedir a outro profissional que memorize.","anotar apenas o nome do medicamento.","aceitar prescrição verbal por telefone em qualquer situação de rotina."]'::jsonb, 0, 'A técnica de "ler de volta" (read back) reduz erros de comunicação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-204', 'tec', null, 'Na limpeza de uma incisão cirúrgica limpa e fechada, o sentido correto é:', '["da incisão (área mais limpa) para a pele ao redor (menos limpa).","da pele ao redor para a incisão.","em movimentos de vaivém sobre a incisão.","não é necessário seguir sentido.","da parte inferior do corpo para a incisão."]'::jsonb, 0, 'Usar uma gaze por movimento, sempre do menos contaminado para o mais contaminado.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-205', 'tec', null, 'A cicatrização por primeira intenção ocorre quando:', '["as bordas da ferida estão aproximadas, como em incisões cirúrgicas suturadas.","a ferida fica aberta e cicatriza por granulação.","a ferida é fechada dias após a abertura.","há grande perda de tecido.","há infecção ativa."]'::jsonb, 0, 'Segunda intenção: bordas afastadas, cicatrização por granulação. Terceira intenção: fechamento tardio.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-206', 'tec', null, 'O tecido de granulação, presente em feridas em processo de cicatrização, tem aspecto:', '["vermelho vivo, úmido e brilhante, com aspecto granuloso.","preto e endurecido.","amarelo e aderido ao leito.","branco e seco.","esverdeado com odor fétido."]'::jsonb, 0, 'Necrose: preta/escura; esfacelo: amarelo; secreção esverdeada e odor sugerem infecção.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-207', 'tec', null, 'Na prevenção de lesão por pressão, é INCORRETO:', '["massagear as proeminências ósseas avermelhadas.","manter a pele limpa e hidratada.","realizar mudança de decúbito.","usar superfícies de redistribuição de pressão.","proteger a pele da umidade excessiva."]'::jsonb, 0, 'A massagem sobre áreas hiperemiadas pode aumentar a lesão tecidual.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-208', 'tec', null, 'A aplicação de ácidos graxos essenciais (AGE) na pele íntegra de pacientes acamados tem como objetivo:', '["hidratar e proteger a pele, auxiliando na prevenção de lesões.","realizar desbridamento de necrose.","tratar infecções fúngicas.","substituir a mudança de decúbito.","cauterizar feridas."]'::jsonb, 0, 'Os AGE mantêm a barreira cutânea, mas não substituem as demais medidas preventivas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-209', 'tec', null, 'A sondagem vesical de demora é um procedimento frequente na assistência. Acerca da técnica e dos cuidados, registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-210', 'tec', null, 'A diferença entre o cateterismo vesical de alívio e o de demora é que, no cateterismo de alívio:', '["o cateter é retirado logo após o esvaziamento da bexiga.","o cateter permanece por vários dias com o balonete insuflado.","a técnica é limpa, dispensando material estéril.","é utilizado exclusivamente para coleta de urocultura em homens.","a bolsa coletora deve ser trocada a cada 6 horas."]'::jsonb, 0, 'No alívio (intermitente), o cateter sem balonete é retirado após o esvaziamento; no de demora, permanece fixado pelo balonete.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-211', 'tec', null, 'Para a coleta de urina para urocultura em paciente com sonda vesical de demora, o procedimento correto é:', '["coletar a amostra pelo dispositivo próprio do sistema (porta de coleta), com seringa estéril, após antissepsia.","coletar a urina diretamente da bolsa coletora.","desconectar a sonda da bolsa para coletar a urina pela extremidade.","trocar a sonda e coletar a urina da bolsa nova após 24 horas.","puncionar a bexiga com agulha comum."]'::jsonb, 0, 'Abrir o sistema e coletar da bolsa aumentam o risco de contaminação da amostra e de infecção.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-212', 'tec', null, 'Na orientação para coleta de urina tipo I (EAS) em paciente sem sonda, recomenda-se:', '["realizar higiene da região genital e coletar o jato médio, preferencialmente da primeira urina da manhã.","coletar todo o volume urinário em recipiente aberto.","coletar o primeiro jato, sem higiene prévia.","coletar a urina do vaso sanitário.","manter o frasco aberto até a entrega no laboratório."]'::jsonb, 0, 'O primeiro jato é desprezado por conter mais microrganismos da uretra; a amostra deve ser entregue rapidamente ao laboratório.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-213', 'tec', null, 'Antes de iniciar a dieta por sonda nasoenteral recém-passada, a confirmação do posicionamento da sonda deve ser feita, preferencialmente, por:', '["exame radiológico.","ausculta após injeção de ar, exclusivamente.","observação de borbulhamento com a ponta da sonda em um copo d''água.","pergunta ao paciente sobre desconforto.","medida externa da sonda."]'::jsonb, 0, 'O raio X é o padrão-ouro para confirmar a posição da sonda antes do início da dieta.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-214', 'tec', null, 'Considerando os cuidados na administração de dieta enteral por sonda, analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-215', 'tec', null, 'A máscara com reservatório (máscara não reinalante) é um dispositivo de oxigenoterapia que:', '["oferece alta concentração de oxigênio, exigindo fluxo suficiente para manter o reservatório inflado.","oferece baixa concentração de oxigênio, com fluxo máximo de 2 L/min.","dispensa a umidificação e o controle do fluxo.","é indicada para oxigenoterapia domiciliar prolongada.","é usada exclusivamente em recém-nascidos."]'::jsonb, 0, 'Com fluxo de 10 a 15 L/min, alcança frações inspiradas elevadas; o reservatório não deve murchar durante a inspiração.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-216', 'tec', null, 'Na aspiração de vias aéreas de paciente intubado, em sistema aberto, utilizando a mesma sonda, a sequência correta é:', '["tubo orotraqueal, depois nasofaringe e por último orofaringe.","orofaringe, depois nasofaringe e por último tubo orotraqueal.","nasofaringe, orofaringe e tubo orotraqueal.","orofaringe e tubo orotraqueal, alternadamente.","a ordem é indiferente, desde que a sonda seja estéril."]'::jsonb, 0, 'Aspira-se do local mais limpo (via aérea inferior, pelo tubo) para o mais contaminado (boca); a sonda não retorna ao tubo após aspirar a boca.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-217', 'tec', null, 'Sobre os cuidados com o paciente traqueostomizado, registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-218', 'tec', null, 'Considerando as diferentes vias de verificação da temperatura corporal, em condições normais, a ordem crescente dos valores é:', '["axilar, oral e retal.","retal, oral e axilar.","oral, axilar e retal.","axilar, retal e oral.","as três vias apresentam valores idênticos."]'::jsonb, 0, 'A temperatura retal é a mais elevada e a axilar, a mais baixa (diferença aproximada de 0,5 °C entre elas).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-219', 'tec', null, 'O déficit de pulso, avaliado pela diferença entre a frequência do pulso apical e a do pulso radial, verificados simultaneamente, é encontrado, por exemplo, em pacientes com:', '["fibrilação atrial.","febre baixa.","hipotermia leve.","ansiedade.","desidratação leve."]'::jsonb, 0, 'Nas arritmias, alguns batimentos não geram onda de pulso palpável na periferia.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-220', 'tec', null, 'Na aferição da pressão arterial, deve-se evitar o membro superior:', '["com fístula arteriovenosa para hemodiálise ou do mesmo lado de mastectomia com esvaziamento axilar.","dominante do paciente.","esquerdo, em todos os pacientes.","de pacientes idosos.","sem acesso venoso periférico."]'::jsonb, 0, 'A compressão pode lesar a fístula; no lado da mastectomia com linfadenectomia, há risco de linfedema.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-221', 'tec', null, 'O uso de manguito com largura menor que a recomendada para a circunferência do braço do paciente provoca:', '["superestimação dos valores da pressão arterial.","subestimação dos valores da pressão arterial.","nenhuma alteração nos valores.","alteração apenas da frequência cardíaca.","erro apenas na pressão diastólica, que fica falsamente baixa."]'::jsonb, 0, 'Manguito estreito superestima a PA; manguito largo demais a subestima.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-222', 'tec', null, 'Um paciente adulto pesa 80 kg e mede 1,60 m. O seu índice de massa corporal (IMC) e a classificação correspondente são:', '["31,25 kg/m² — obesidade grau I.","50 kg/m² — obesidade grau III.","25 kg/m² — eutrofia.","28,5 kg/m² — sobrepeso.","20 kg/m² — baixo peso."]'::jsonb, 0, 'IMC = peso ÷ altura² = 80 ÷ 2,56 = 31,25. Obesidade grau I: 30 a 34,9.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-223', 'tec', null, 'Na medida da circunferência abdominal, a fita métrica deve ser posicionada:', '["no ponto médio entre a última costela e a crista ilíaca.","sobre o apêndice xifoide.","na altura dos mamilos.","sobre a sínfise púbica.","na região mais estreita do tórax."]'::jsonb, 0, 'É a referência mais usada; a medida é feita ao final da expiração, com o paciente em pé.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-224', 'tec', null, 'Em adultos, é considerada oligúria a diurese inferior a:', '["400 mL em 24 horas.","1.500 mL em 24 horas.","100 mL em 1 hora.","2.000 mL em 24 horas.","800 mL em 12 horas."]'::jsonb, 0, 'Oligúria: < 400 mL/24 h (ou < 0,5 mL/kg/h); anúria: < 100 mL/24 h.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-225', 'tec', null, 'Associe os termos às suas definições.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-226', 'tec', null, 'A eliminação de fezes escuras, pastosas, de odor fétido e aspecto de borra de café, decorrente da presença de sangue digerido, é denominada:', '["melena.","hematoquezia.","acolia.","esteatorreia.","hematêmese."]'::jsonb, 0, 'Melena sugere sangramento digestivo alto. Hematoquezia: sangue vivo nas fezes; acolia: fezes descoradas; esteatorreia: gordura nas fezes.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-227', 'tec', null, 'A eliminação de sangue proveniente das vias respiratórias, geralmente vermelho vivo e espumoso, acompanhada de tosse, é denominada:', '["hemoptise.","hematêmese.","epistaxe.","melena.","hematúria."]'::jsonb, 0, 'Hematêmese é o vômito com sangue (origem digestiva); epistaxe é o sangramento nasal.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-228', 'tec', null, 'A presença de depressão na pele que persiste por alguns segundos após a compressão digital sobre uma área edemaciada, como a região pré-tibial, caracteriza:', '["o sinal de Godet (cacifo positivo).","o sinal de Homans.","o sinal de Blumberg.","o sinal de Murphy.","o sinal de Babinski."]'::jsonb, 0, 'O sinal do cacifo indica edema depressível.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-229', 'tec', null, 'A coloração azulada da pele e das mucosas, mais evidente nos lábios, na língua e nas extremidades, decorrente do aumento da hemoglobina não oxigenada, é denominada:', '["cianose.","icterícia.","palidez.","rubor.","petéquia."]'::jsonb, 0, 'Cianose central (lábios, língua) indica hipoxemia; a periférica (extremidades) pode decorrer de vasoconstrição ou má perfusão.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-230', 'tec', null, 'Sobre os princípios de mecânica corporal na mobilização de pacientes, analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-231', 'tec', null, 'Na transferência do paciente do leito para a cadeira de rodas, um cuidado essencial para a segurança é:', '["travar as rodas da cadeira e da cama antes da transferência.","manter as rodas destravadas para facilitar o movimento.","realizar a transferência sem avisar o paciente.","posicionar a cadeira no lado mais distante do leito.","elevar o leito à altura máxima."]'::jsonb, 0, 'Travar as rodas evita deslocamentos e quedas; a cama deve estar baixa e o paciente, orientado.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-232', 'tec', null, 'A posição em que o paciente fica ajoelhado, com o tórax apoiado no leito, utilizada em exames proctológicos, é a:', '["genupeitoral.","de Fowler.","de Trendelenburg.","ginecológica.","ortostática."]'::jsonb, 0, 'Na posição genupeitoral, os joelhos e o tórax ficam apoiados no leito.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-233', 'tec', null, 'A posição de semi-Fowler, recomendada para pacientes com dieta enteral e para prevenção de broncoaspiração, consiste em manter a cabeceira elevada em aproximadamente:', '["30° a 45°.","0°.","90°.","10°.","60° a 90°, com as pernas elevadas."]'::jsonb, 0, 'A Fowler clássica fica em 45° a 60°; a Fowler alta, a cerca de 90°.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-234', 'tec', null, 'Na higiene íntima feminina realizada no leito, o sentido correto da limpeza é:', '["da região anterior (púbis) para a posterior (ânus).","da região anal para a púbica.","em movimentos circulares a partir do ânus.","em vaivém, com a mesma parte da compressa.","aleatório, desde que se use sabão."]'::jsonb, 0, 'O sentido anteroposterior evita levar microrganismos da região anal para o meato uretral e a vagina.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-235', 'tec', null, 'Na coleta de sangue venoso com sistema a vácuo, para evitar contaminação por aditivos entre os tubos, a ordem de coleta recomendada inicia-se pelo frasco de:', '["hemocultura, seguido do tubo com citrato (tampa azul).","EDTA (tampa roxa), seguido do tubo de soro.","fluoreto (tampa cinza), seguido do citrato.","heparina (tampa verde), seguido da hemocultura.","qualquer tubo, pois a ordem não interfere."]'::jsonb, 0, 'Ordem usual: hemocultura → citrato (azul) → soro (vermelho/amarelo) → heparina (verde) → EDTA (roxo) → fluoreto (cinza).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-236', 'tec', null, 'Na coleta de sangue venoso, o garrote deve permanecer aplicado por, no máximo:', '["1 minuto.","5 minutos.","10 minutos.","15 minutos.","30 segundos após a retirada da agulha."]'::jsonb, 0, 'O garroteamento prolongado causa hemoconcentração e altera resultados, como potássio e proteínas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-237', 'tec', null, 'Sobre a coleta de hemocultura, analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-238', 'tec', null, 'Antes da punção da artéria radial para coleta de gasometria, realiza-se um teste para avaliar a circulação colateral da mão pela artéria ulnar. Esse teste é denominado:', '["teste de Allen.","teste do laço.","manobra de Valsalva.","teste de Romberg.","prova de Rivalta."]'::jsonb, 0, 'Comprimem-se as artérias radial e ulnar e libera-se a ulnar: o retorno rápido da coloração indica circulação colateral adequada.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-239', 'tec', null, 'Segundo as recomendações da ANVISA para prevenção de infecções relacionadas a cateteres periféricos em adultos, é correto:', '["não trocar rotineiramente o cateter periférico em intervalo inferior a 96 horas, avaliando diariamente o sítio de inserção.","trocar o cateter a cada 24 horas, mesmo sem sinais de complicação.","preferir a inserção em membros inferiores.","manter o cateter indefinidamente, enquanto houver refluxo de sangue.","realizar a punção sobre áreas de flexão, para melhor fixação."]'::jsonb, 0, 'Preferem-se os membros superiores, evitando articulações; o sítio deve ser inspecionado diariamente.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-240', 'tec', null, 'Na instalação de hemocomponentes, o equipo deve ser:', '["específico, com filtro, e trocado a cada bolsa.","o mesmo do soro em curso, para evitar nova punção.","trocado a cada 7 dias.","utilizado sem filtro, para não reduzir a vazão.","compartilhado com a infusão de medicamentos."]'::jsonb, 0, 'Usa-se equipo próprio com filtro; não se administram medicamentos na mesma via do hemocomponente.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-241', 'tec', null, 'Sobre os cuidados de enfermagem na transfusão de hemocomponentes, registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-242', 'tec', null, 'Durante a transfusão de concentrado de hemácias, o paciente apresenta calafrios, febre e dor lombar. A primeira conduta da equipe de enfermagem é:', '["interromper a transfusão, manter o acesso venoso com soro fisiológico e comunicar imediatamente o enfermeiro e o médico.","aumentar a velocidade de infusão para terminar logo.","administrar antitérmico e continuar a transfusão.","retirar o acesso venoso e descartar a bolsa no lixo comum.","aguardar o término da bolsa para avaliar o paciente."]'::jsonb, 0, 'Suspeita de reação transfusional: parar a infusão, manter a veia, avaliar sinais vitais e notificar; a bolsa e o equipo são preservados para investigação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-243', 'tec', null, 'Associe os termos às suas definições.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-244', 'tec', null, 'Na realização do eletrocardiograma de 12 derivações, o eletrodo precordial V1 deve ser posicionado:', '["no 4º espaço intercostal, na borda direita do esterno.","no 5º espaço intercostal, na linha hemiclavicular esquerda.","no 4º espaço intercostal, na borda esquerda do esterno.","no 5º espaço intercostal, na linha axilar média esquerda.","sobre o apêndice xifoide."]'::jsonb, 0, 'V1: 4º EIC à direita do esterno; V2: 4º EIC à esquerda; V4: 5º EIC na linha hemiclavicular; V6: linha axilar média.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-245', 'tec', null, 'No padrão de cores mais utilizado no Brasil para os eletrodos dos membros no eletrocardiograma, o eletrodo do braço direito é identificado pela cor:', '["vermelha.","amarela.","verde.","preta.","branca."]'::jsonb, 0, 'Braço direito: vermelho; braço esquerdo: amarelo; perna esquerda: verde; perna direita: preto.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-246', 'tec', null, 'Para a coleta de escarro para baciloscopia (pesquisa de BAAR), o paciente deve ser orientado a:', '["coletar, preferencialmente, ao despertar, após enxaguar a boca com água, uma amostra de escarro proveniente de tosse profunda, e não de saliva.","escovar os dentes com creme dental imediatamente antes da coleta.","coletar a saliva acumulada ao longo do dia.","manter o pote aberto até a entrega no laboratório.","coletar a amostra no banheiro da unidade, na presença de outros pacientes."]'::jsonb, 0, 'A amostra deve ser coletada em local aberto e ventilado, em pote identificado e bem fechado, protegido da luz.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-247', 'tec', null, 'Nas primeiras horas após uma entorse de tornozelo, sem fratura, a aplicação de frio local está indicada principalmente porque:', '["promove vasoconstrição, reduzindo o edema e a dor.","promove vasodilatação, acelerando a reabsorção do hematoma.","aumenta o metabolismo local.","estimula o sangramento para limpar a lesão.","substitui a imobilização."]'::jsonb, 0, 'O frio é indicado na fase aguda; o calor, que provoca vasodilatação, é usado depois, na fase de reabsorção.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-248', 'tec', null, 'Na ausculta pulmonar, os ruídos agudos e musicais, mais audíveis na expiração e associados ao estreitamento das vias aéreas, como na crise asmática, são os:', '["sibilos.","estertores crepitantes.","roncos.","atritos pleurais.","murmúrios vesiculares normais."]'::jsonb, 0, 'Crepitantes: ar passando por alvéolos com líquido; roncos: secreção em vias aéreas de maior calibre; atrito pleural: inflamação da pleura.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-249', 'tec', null, 'Os valores de glicemia de jejum considerados normais para adultos, segundo a Sociedade Brasileira de Diabetes, são:', '["inferiores a 100 mg/dL.","entre 100 e 125 mg/dL.","iguais ou superiores a 126 mg/dL.","inferiores a 60 mg/dL.","entre 140 e 199 mg/dL."]'::jsonb, 0, 'Jejum < 100: normal; 100–125: pré-diabetes; ≥ 126: diabetes (confirmado).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-250', 'tec', null, 'No balanço hídrico, registram-se os ganhos e as perdas de líquidos do paciente. Registre V para os itens que são contabilizados como perdas e F para os que são ganhos.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-251', 'tec', null, 'Um paciente apresenta respiração ruidosa, com sons semelhantes a gorgolejo, decorrente do acúmulo de secreção nas vias aéreas superiores, e não consegue tossir de forma eficaz. A intervenção prioritária de enfermagem é:', '["aspirar as vias aéreas, conforme prescrição e técnica adequada, e posicionar o paciente com a cabeceira elevada.","oferecer água por via oral.","deitar o paciente em decúbito dorsal horizontal.","administrar sedativo para diminuir a ansiedade.","aguardar a visita médica sem intervir."]'::jsonb, 0, 'Manter a permeabilidade das vias aéreas é prioridade; o decúbito elevado favorece a ventilação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-252', 'tec', null, 'Na admissão de um paciente na unidade de internação, é atribuição da equipe de enfermagem, EXCETO:', '["prescrever a terapêutica medicamentosa do paciente.","receber e acomodar o paciente, orientando-o sobre a rotina da unidade.","verificar e registrar os sinais vitais, o peso e a altura.","identificar o paciente com pulseira, conforme protocolo.","listar e registrar os pertences, conforme norma da instituição."]'::jsonb, 0, 'A prescrição de medicamentos é atribuição médica (ou do enfermeiro em protocolos específicos), não do técnico.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-253', 'tec', null, 'Ao realizar o banho no leito em paciente com sonda vesical, a higiene do cateter deve ser feita:', '["do meato urinário em direção à extremidade distal do cateter, com água e sabão.","da extremidade distal em direção ao meato urinário.","apenas com álcool 70%, em movimentos de vaivém.","somente uma vez por semana.","desconectando-se a sonda da bolsa coletora."]'::jsonb, 0, 'A limpeza do meato para fora evita levar microrganismos para a uretra; o sistema permanece fechado.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-254', 'tec', null, 'O paciente que apresenta confusão mental aguda, com flutuação da atenção ao longo do dia, piora à noite e alterações do ciclo sono-vigília, durante uma internação, pode estar apresentando:', '["delirium.","demência avançada estável.","depressão maior.","esquizofrenia de início tardio.","comportamento esperado do envelhecimento."]'::jsonb, 0, 'O delirium é agudo e flutuante e exige investigação da causa (infecção, medicamentos, distúrbios metabólicos).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-255', 'tec', null, 'Na nebulização com soro fisiológico e medicamento broncodilatador, o fluxo de ar comprimido ou oxigênio geralmente utilizado é de:', '["6 a 8 L/min.","1 a 2 L/min.","15 L/min, no mínimo.","0,5 L/min.","25 L/min."]'::jsonb, 0, 'Esse fluxo gera névoa adequada; o paciente deve ficar sentado, respirando pela boca com a máscara bem ajustada.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-256', 'tec', null, 'No preparo do corpo após o óbito, em situação em que não há indicação de necropsia pelo IML, é correto:', '["retirar sondas, drenos e cateteres, realizar a higiene, tamponar orifícios quando indicado, identificar o corpo e registrar o horário do óbito constatado pelo médico.","aguardar 24 horas para iniciar o preparo.","manter todos os dispositivos e entregar o corpo sem higiene.","identificar o corpo apenas pelo número do leito.","liberar o corpo antes da constatação do óbito pelo médico."]'::jsonb, 0, 'O óbito é constatado e declarado pelo médico; a enfermagem prepara o corpo respeitando a dignidade e as normas institucionais.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-257', 'tec', null, 'Na verificação da frequência respiratória, recomenda-se:', '["contar os movimentos respiratórios durante 1 minuto, sem que o paciente perceba, logo após a verificação do pulso.","pedir ao paciente que respire normalmente enquanto se conta.","contar por 10 segundos e multiplicar por 6, em qualquer situação.","verificar apenas em pacientes com dispneia.","contar os movimentos somente durante o sono."]'::jsonb, 0, 'Quando percebe a contagem, o paciente tende a alterar o ritmo respiratório.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-258', 'tec', null, 'No paciente com dreno de tórax em selo d''água, a oscilação da coluna de líquido no frasco acompanhando a respiração indica:', '["que o sistema está pérvio e funcionante.","obstrução do dreno.","necessidade imediata de retirada do dreno.","vazamento de ar para o ambiente.","infecção do sítio de inserção."]'::jsonb, 0, 'A ausência de oscilação pode indicar obstrução, dobra do tubo ou reexpansão pulmonar completa; deve ser comunicada.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-259', 'tec', null, 'No cuidado ao paciente com dreno de tórax em selo d''água, é correto:', '["manter o frasco de drenagem sempre abaixo do nível do tórax e o selo d''água no nível padronizado.","manter o frasco acima do nível do tórax durante o transporte.","clampear o dreno rotineiramente durante todo o transporte.","esvaziar o frasco sem clampear o dreno, com o paciente em qualquer posição.","retirar o selo d''água para medir o débito."]'::jsonb, 0, 'O frasco acima do tórax permite refluxo do líquido para a cavidade pleural; o clampeamento é feito apenas por curto tempo e quando indicado.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-260', 'tec', null, 'Ao verificar a glicemia capilar de um paciente diabético, o técnico obtém valor de 52 mg/dL; o paciente está sudoreico, trêmulo e consciente. A conduta inicial adequada é:', '["oferecer carboidrato de absorção rápida por via oral, comunicar o enfermeiro e repetir a glicemia em cerca de 15 minutos.","administrar a dose de insulina prevista para o horário.","manter o paciente em jejum até a visita médica.","oferecer uma refeição rica em gordura.","aguardar nova verificação em 2 horas."]'::jsonb, 0, 'Hipoglicemia com paciente consciente: 15 g de carboidrato simples e reavaliação em 15 minutos (regra dos 15).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-261', 'tec', null, 'Sobre a prevenção de quedas em pacientes internados, analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-262', 'tec', null, 'No paciente em uso de sonda nasogástrica aberta em drenagem, o técnico observa a saída de 600 mL de conteúdo esverdeado em 12 horas. A conduta adequada é:', '["registrar o volume e o aspecto no balanço hídrico e comunicar o enfermeiro.","fechar a sonda para reduzir a perda de líquido.","retirar a sonda imediatamente.","descartar o conteúdo sem registro.","oferecer dieta via oral para compensar a perda."]'::jsonb, 0, 'Perdas por sonda devem ser mensuradas e registradas; volumes elevados podem causar distúrbios hidroeletrolíticos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-263', 'tec', null, 'Na medida da altura uterina, do peso ou dos sinais vitais, o registro adequado no prontuário deve:', '["ser feito logo após o procedimento, com data, horário, valores obtidos, assinatura e número de inscrição no COREN.","ser feito apenas ao final do plantão, de memória.","conter apenas os valores alterados.","ser realizado a lápis, para permitir correções.","ser feito por outro profissional, que não realizou o procedimento."]'::jsonb, 0, 'Os registros devem ser imediatos, completos, legíveis, sem rasuras e identificados (Resolução COFEN 514/2016).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-264', 'tec', null, 'Ao preparar o paciente para exame de ultrassonografia da pelve (via abdominal), uma orientação habitual é:', '["ingerir líquidos e manter a bexiga cheia, conforme orientação do serviço.","esvaziar completamente a bexiga imediatamente antes do exame.","realizar lavagem intestinal com bário.","permanecer em jejum absoluto de 24 horas.","suspender todos os medicamentos de uso contínuo."]'::jsonb, 0, 'A bexiga cheia funciona como janela acústica para visualizar os órgãos pélvicos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-265', 'tec', null, 'O paciente que vai realizar tomografia com contraste iodado deve ser questionado, antes do exame, principalmente sobre:', '["alergias prévias a contraste e a função renal.","o tipo sanguíneo.","a data da última vacinação.","o uso de lentes de contato.","a presença de tatuagens recentes."]'::jsonb, 0, 'O contraste iodado pode causar reações alérgicas e nefropatia; pacientes em uso de metformina podem ter orientações específicas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-266', 'tec', null, 'Antes de um exame de ressonância magnética, é fundamental investigar e retirar:', '["objetos metálicos e verificar a presença de marca-passo, implantes ou próteses metálicas.","próteses dentárias de resina, apenas.","roupas de algodão.","curativos simples.","a pulseira de identificação."]'::jsonb, 0, 'O campo magnético intenso atrai objetos metálicos e pode interferir em dispositivos implantados.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-267', 'tec', null, 'Foram prescritos 1.000 mL de soro fisiológico 0,9% para correr em 24 horas, com equipo macrogotas. O gotejamento será de aproximadamente:', '["14 gotas/min.","42 gotas/min.","28 gotas/min.","7 gotas/min.","21 gotas/min."]'::jsonb, 0, 'Gotas/min = V ÷ (T × 3) = 1.000 ÷ 72 ≈ 13,9 ≈ 14 gotas/min.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-268', 'tec', null, 'Foram prescritos 500 mL de soro glicosado 5% para correr em 6 horas, em equipo microgotas. O gotejamento será de aproximadamente:', '["83 microgotas/min.","28 microgotas/min.","50 microgotas/min.","166 microgotas/min.","125 microgotas/min."]'::jsonb, 0, 'Microgotas/min = V ÷ T(h) = 500 ÷ 6 ≈ 83.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-269', 'tec', null, 'Um soro está correndo a 42 microgotas por minuto. A vazão correspondente, em mL/h, é de:', '["42 mL/h.","14 mL/h.","126 mL/h.","84 mL/h.","21 mL/h."]'::jsonb, 0, 'Como 1 mL = 60 microgotas, o número de microgotas por minuto é igual ao número de mL por hora.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-270', 'tec', null, 'Uma prescrição indica 60 mL/h de soro fisiológico, mas não há bomba de infusão disponível. Com equipo macrogotas, o gotejamento deverá ser de:', '["20 gotas/min.","60 gotas/min.","10 gotas/min.","40 gotas/min.","3 gotas/min."]'::jsonb, 0, '60 mL/h = 1 mL/min = 20 gotas/min.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-271', 'tec', null, 'Um frasco de 500 mL de soro está sendo infundido a 25 gotas/min, em equipo macrogotas. O tempo aproximado para o término da infusão é de:', '["6 horas e 40 minutos.","4 horas.","8 horas e 20 minutos.","5 horas.","3 horas e 20 minutos."]'::jsonb, 0, '500 mL × 20 gotas = 10.000 gotas; 10.000 ÷ 25 = 400 minutos = 6 h 40 min.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-272', 'tec', null, 'Um soro foi infundido a 30 gotas/min, em equipo macrogotas, durante 2 horas. O volume infundido nesse período foi de:', '["180 mL.","60 mL.","360 mL.","120 mL.","90 mL."]'::jsonb, 0, '30 gotas × 120 min = 3.600 gotas; 3.600 ÷ 20 = 180 mL.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-273', 'tec', null, 'Foram prescritos 1.500 mL de solução para correr em 24 horas em bomba de infusão. A vazão a ser programada é de:', '["62,5 mL/h.","125 mL/h.","41,6 mL/h.","15 mL/h.","250 mL/h."]'::jsonb, 0, '1.500 ÷ 24 = 62,5 mL/h.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-274', 'tec', null, 'Um frasco-ampola de 1 g de antibiótico foi diluído em 4 mL de água destilada, sem acréscimo de volume pelo pó. Para administrar 600 mg, deve-se aspirar:', '["2,4 mL.","1,5 mL.","3 mL.","0,6 mL.","6 mL."]'::jsonb, 0, '1.000 mg — 4 mL; 600 mg — x → x = 2,4 mL.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-275', 'tec', null, 'Um frasco de ampicilina 1 g foi diluído em 5 mL. Foram prescritos 250 mg. Deve-se aspirar:', '["1,25 mL.","2,5 mL.","0,25 mL.","5 mL.","1 mL."]'::jsonb, 0, '1.000 mg — 5 mL; 250 mg — x → x = 1,25 mL.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-276', 'tec', null, 'Uma ampola de glicose a 50% com 10 mL contém:', '["5 g de glicose.","50 g de glicose.","0,5 g de glicose.","10 g de glicose.","1 g de glicose."]'::jsonb, 0, '50% = 50 g em 100 mL → em 10 mL há 5 g.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-277', 'tec', null, 'Uma ampola de cloreto de sódio a 20% com 10 mL contém:', '["2 g de NaCl.","20 g de NaCl.","0,2 g de NaCl.","10 g de NaCl.","0,9 g de NaCl."]'::jsonb, 0, '20% = 20 g em 100 mL → em 10 mL há 2 g.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-278', 'tec', null, 'Foi prescrito para uma criança de 20 kg um medicamento na dose de 15 mg/kg. A apresentação disponível é de 100 mg/mL. Deve-se administrar:', '["3 mL.","1,5 mL.","15 mL.","0,3 mL.","30 mL."]'::jsonb, 0, '15 mg × 20 kg = 300 mg; 100 mg — 1 mL; 300 mg — x → x = 3 mL.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-279', 'tec', null, 'Utilizando seringa de insulina graduada em 100 UI por 1 mL, o volume correspondente a 15 UI é de:', '["0,15 mL.","1,5 mL.","0,015 mL.","15 mL.","0,5 mL."]'::jsonb, 0, '100 UI — 1 mL; 15 UI — x → x = 0,15 mL. Sempre que possível, usa-se a seringa graduada em UI.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-280', 'tec', null, 'Entre as insulinas abaixo, a única que pode ser administrada por via endovenosa é a:', '["insulina regular.","insulina NPH.","insulina glargina.","insulina detemir.","pré-mistura NPH/regular."]'::jsonb, 0, 'A insulina regular é a de escolha para infusão endovenosa, por exemplo, na cetoacidose diabética.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-281', 'tec', null, 'Sobre as características das insulinas, registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-282', 'tec', null, 'Na aplicação de enoxaparina (heparina de baixo peso molecular) por via subcutânea, com seringa pré-preenchida, é recomendado:', '["aplicar na região abdominal, sem retirar a bolha de ar da seringa e sem massagear o local.","aplicar na região glútea, por via intramuscular.","retirar a bolha de ar e massagear vigorosamente o local.","aspirar antes de injetar para verificar retorno de sangue.","aplicar sempre no mesmo local, para facilitar a absorção."]'::jsonb, 0, 'A bolha garante a administração de toda a dose; massagem e aspiração aumentam o risco de hematoma. Faz-se rodízio dos locais.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-283', 'tec', null, 'A heparina não fracionada administrada por via endovenosa contínua tem seu efeito monitorado, principalmente, pelo exame de:', '["tempo de tromboplastina parcial ativada (TTPa).","RNI (INR).","glicemia.","hemoglobina glicada.","creatinina."]'::jsonb, 0, 'O RNI é usado para monitorar a varfarina; o antídoto da heparina é a protamina.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-284', 'tec', null, 'São sinais e sintomas sugestivos de intoxicação digitálica:', '["náuseas, vômitos, alterações visuais (visão amarelada) e bradicardia.","hipertensão e taquicardia sinusal.","febre e rash cutâneo.","hiperglicemia e poliúria.","tosse seca persistente."]'::jsonb, 0, 'Hipocalemia e insuficiência renal aumentam o risco de intoxicação pela digoxina.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-285', 'tec', null, 'Paciente em uso de furosemida deve ser monitorado, principalmente, quanto ao risco de:', '["hipocalemia (redução do potássio) e desidratação.","hipercalemia grave.","hiperglicemia aguda.","retenção urinária.","ganho de peso por retenção hídrica."]'::jsonb, 0, 'A furosemida é diurético de alça que aumenta a perda de potássio; o balanço hídrico e o peso diário ajudam no acompanhamento.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-286', 'tec', null, 'A espironolactona é um diurético que exige atenção ao risco de:', '["hipercalemia, por ser poupador de potássio.","hipocalemia grave.","hipoglicemia.","sangramento digestivo.","depressão respiratória."]'::jsonb, 0, 'O risco é maior quando associada a IECA ou a suplementos de potássio, e em pacientes com insuficiência renal.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-287', 'tec', null, 'Um paciente hipertenso em uso de captopril queixa-se de tosse seca persistente. Esse efeito adverso é característico da classe dos:', '["inibidores da enzima conversora de angiotensina (IECA).","betabloqueadores.","bloqueadores dos canais de cálcio.","diuréticos tiazídicos.","antagonistas da aldosterona."]'::jsonb, 0, 'A tosse seca é efeito comum dos IECA (captopril, enalapril) e deve ser comunicada.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-288', 'tec', null, 'O dinitrato de isossorbida sublingual, usado na angina, pode causar como efeitos adversos:', '["cefaleia e hipotensão.","bradicardia e hipertensão.","hiperglicemia e sede.","constipação e retenção urinária.","sonolência profunda e depressão respiratória."]'::jsonb, 0, 'Os nitratos são vasodilatadores; seu uso com inibidores da fosfodiesterase (como a sildenafila) é contraindicado pelo risco de hipotensão grave.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-289', 'tec', null, 'O uso de ácido acetilsalicílico em crianças e adolescentes com quadros virais, como varicela e influenza, deve ser evitado pelo risco de:', '["síndrome de Reye.","síndrome de Down.","síndrome nefrótica.","síndrome de Guillain-Barré.","síndrome de Cushing."]'::jsonb, 0, 'A síndrome de Reye é rara e grave, com acometimento hepático e encefalopatia.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-290', 'tec', null, 'Paciente em uso prolongado de corticoide sistêmico (como a prednisona) deve ser orientado a:', '["não suspender o medicamento abruptamente, pois a retirada deve ser gradual, conforme prescrição.","suspender o medicamento assim que os sintomas melhorarem.","tomar o medicamento apenas à noite, em jejum.","dobrar a dose quando esquecer uma tomada.","evitar a monitorização da glicemia."]'::jsonb, 0, 'A suspensão abrupta pode causar insuficiência adrenal; corticoides também podem elevar a glicemia e a pressão arterial.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-291', 'tec', null, 'Os antibióticos aminoglicosídeos, como a gentamicina e a amicacina, exigem monitorização por apresentarem potencial de:', '["nefrotoxicidade e ototoxicidade.","hepatotoxicidade e hipoglicemia.","cardiotoxicidade e hipertensão.","depressão respiratória e miose.","fotossensibilidade e queda de cabelo."]'::jsonb, 0, 'Devem-se observar a função renal, a diurese e queixas auditivas (zumbido, perda auditiva).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-292', 'tec', null, 'A infusão rápida de vancomicina pode provocar rubor intenso, prurido e hipotensão (síndrome do homem vermelho). Para prevenir essa reação, recomenda-se:', '["diluir adequadamente e infundir lentamente, em pelo menos 60 minutos.","administrar em bolus rápido.","administrar por via intramuscular.","aplicar compressas quentes durante a infusão.","suspender a hidratação venosa."]'::jsonb, 0, 'A velocidade de infusão é o principal fator desencadeante da reação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-293', 'tec', null, 'Sobre os cuidados de enfermagem a pacientes em uso de opioides, como a morfina, analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-294', 'tec', null, 'Pacientes idosos em uso de benzodiazepínicos, como o diazepam, devem ser acompanhados, principalmente, quanto ao risco de:', '["sonolência, confusão e quedas.","hipertensão arterial grave.","hiperatividade e insônia.","hiperglicemia.","sangramento gengival."]'::jsonb, 0, 'Os benzodiazepínicos reduzem o estado de alerta e aumentam o risco de quedas e fraturas em idosos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-295', 'tec', null, 'O haloperidol, antipsicótico de uso frequente em emergências psiquiátricas, pode causar como efeitos adversos:', '["sintomas extrapiramidais, como rigidez, tremores e distonia aguda.","hipoglicemia grave.","sangramentos digestivos.","tosse seca persistente.","ototoxicidade."]'::jsonb, 0, 'Os sintomas extrapiramidais devem ser observados e comunicados.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-296', 'tec', null, 'Sobre o horário de administração de alguns medicamentos de uso oral, analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-297', 'tec', null, 'Um antibiótico foi prescrito de 8 em 8 horas, e a primeira dose foi administrada às 6h. As próximas doses, no mesmo dia, devem ser administradas às:', '["14h e 22h.","12h e 18h.","10h e 18h.","16h e 24h.","13h e 20h."]'::jsonb, 0, '6h + 8h = 14h; 14h + 8h = 22h. Respeitar o intervalo mantém o nível sérico terapêutico.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-298', 'tec', null, 'Ao reconstituir um medicamento que será utilizado em mais de uma dose, o frasco deve ser:', '["identificado com data, horário da diluição, concentração e assinatura, respeitando o prazo de estabilidade indicado pelo fabricante.","guardado sem identificação, pois a validade é a mesma do pó.","mantido aberto, para facilitar a próxima aspiração.","utilizado por até 30 dias, em qualquer condição.","armazenado junto aos medicamentos de outros pacientes, sem rótulo."]'::jsonb, 0, 'Após a diluição, a estabilidade costuma ser menor; o frasco deve ser identificado e armazenado conforme orientação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-299', 'tec', null, 'Na aplicação de insulina por via subcutânea em adulto, com agulha de 4 mm, recomenda-se, em geral:', '["inserir a agulha a 90°, sem necessidade de prega cutânea na maioria dos adultos.","inserir a agulha a 15°, formando pápula.","inserir a agulha a 45°, sempre com prega e aspiração prévia.","aplicar sempre por via intramuscular no deltoide.","aplicar sempre no mesmo ponto, para melhor absorção."]'::jsonb, 0, 'Com agulhas curtas, a aplicação a 90° sem prega é segura na maioria dos adultos; em crianças e pessoas magras, pode-se usar prega ou 45°.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-300', 'tec', null, 'Na via intradérmica, como na aplicação da prova tuberculínica (PPD), o volume aplicado é de:', '["0,1 mL.","1 mL.","2 mL.","0,5 mL, sempre.","5 mL."]'::jsonb, 0, 'A via intradérmica comporta pequenos volumes (geralmente até 0,5 mL); no PPD, aplica-se 0,1 mL, formando pápula.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-301', 'tec', null, 'Durante a infusão de um medicamento vesicante por acesso periférico, o paciente queixa-se de dor e o técnico observa edema e palidez ao redor do cateter. A conduta inicial adequada é:', '["interromper imediatamente a infusão, manter o cateter no local até orientação, comunicar o enfermeiro e seguir o protocolo institucional de extravasamento.","aumentar a velocidade para terminar a infusão.","massagear o local para dispersar o medicamento.","lavar o cateter com soro fisiológico em bolus.","aplicar torniquete acima do local."]'::jsonb, 0, 'No extravasamento de vesicantes, a conduta segue protocolo específico (aspiração do resíduo, antídoto e compressa conforme o medicamento).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-302', 'tec', null, 'Para a administração de supositório por via retal em adulto, o paciente deve ser posicionado, preferencialmente, em:', '["decúbito lateral esquerdo (posição de Sims), com o supositório introduzido além do esfíncter anal interno.","decúbito dorsal com as pernas estendidas.","posição de Trendelenburg.","posição ortostática, sem orientação adicional.","decúbito ventral com a cabeceira elevada a 90°."]'::jsonb, 0, 'A posição de Sims acompanha a anatomia do reto e do sigmoide; o paciente deve reter o supositório pelo tempo orientado.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-303', 'tec', null, 'Sobre a administração de colírios, registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-304', 'tec', null, 'Na administração de medicamento otológico em criança menor de 3 anos, para retificar o conduto auditivo, deve-se tracionar o pavilhão auricular:', '["para baixo e para trás.","para cima e para trás.","para cima e para a frente.","para baixo e para a frente.","não é necessário tracionar."]'::jsonb, 0, 'Em adultos e crianças maiores, traciona-se o pavilhão para cima e para trás.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-305', 'tec', null, 'O paciente em uso de corticoide inalatório (bombinha) deve ser orientado a:', '["enxaguar a boca com água e cuspir após cada uso, para prevenir candidíase oral.","engolir a água após o enxágue.","usar o medicamento apenas durante as crises.","evitar o uso de espaçador.","aplicar o jato com a boca aberta, longe dos lábios, sem coordenação com a respiração."]'::jsonb, 0, 'O espaçador melhora a deposição pulmonar; o enxágue reduz efeitos locais como candidíase e rouquidão.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-306', 'tec', null, 'Na aplicação de adesivos transdérmicos (por exemplo, de nicotina ou de analgésicos), é correto:', '["remover o adesivo anterior, fazer rodízio do local e aplicar sobre pele íntegra, limpa e seca.","aplicar o novo adesivo sobre o anterior.","cortar o adesivo ao meio para reduzir a dose, sem orientação.","aplicar sobre áreas com lesão para melhor absorção.","aquecer o local com bolsa térmica após a aplicação."]'::jsonb, 0, 'O calor aumenta a absorção e pode causar toxicidade; o rodízio evita irritação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-307', 'tec', null, 'No armazenamento de medicamentos potencialmente perigosos, como o cloreto de potássio concentrado, a recomendação é:', '["armazená-los separados dos demais, com identificação de alerta, e restringir sua disponibilidade nas unidades.","deixá-los ao lado das ampolas de água destilada, para facilitar a diluição.","armazená-los na mesma gaveta do soro fisiológico.","dispensar a identificação diferenciada.","manter grande estoque em todas as enfermarias."]'::jsonb, 0, 'Essas medidas reduzem trocas e erros graves; a dupla checagem também é recomendada na administração.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-308', 'tec', null, 'Diante da ocorrência de um erro de medicação, analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-309', 'tec', null, 'Associe as siglas às respectivas vias de administração.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-310', 'tec', null, 'Em paciente em uso de anticoagulante, deve-se evitar, sempre que possível, a administração de medicamentos por via:', '["intramuscular, pelo risco de hematoma.","oral.","sublingual.","tópica.","inalatória."]'::jsonb, 0, 'A via IM pode provocar hematomas extensos em pacientes anticoagulados.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-311', 'tec', null, 'A penicilina benzatina pode ser administrada na Atenção Básica, desde que:', '["haja profissionais capacitados e material e medicamentos disponíveis para o atendimento de eventual reação anafilática.","o paciente realize teste cutâneo de alergia em todos os casos.","seja aplicada por via endovenosa.","seja administrada apenas em hospitais.","o paciente tenha mais de 60 anos."]'::jsonb, 0, 'O receio de anafilaxia não deve impedir a aplicação na APS, essencial para o tratamento da sífilis; o serviço deve estar preparado para o atendimento.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-312', 'tec', null, 'A sigla "SOS" ou a expressão "se necessário" em uma prescrição indica que o medicamento:', '["deve ser administrado apenas quando o paciente apresentar a condição indicada, respeitando o intervalo mínimo prescrito.","deve ser administrado obrigatoriamente em todos os horários.","pode ser administrado em qualquer dose, a critério do técnico.","deve ser administrado apenas no período noturno.","foi suspenso pelo médico."]'::jsonb, 0, 'O registro deve indicar o motivo, o horário e a resposta do paciente.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-313', 'tec', null, 'Na administração de medicamentos, o "certo" que consiste em verificar, após a administração, se o medicamento teve o efeito esperado e se houve reações adversas é a:', '["resposta certa.","via certa.","hora certa.","forma certa.","orientação certa."]'::jsonb, 0, 'A observação da resposta e seu registro completam o processo seguro de administração.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-314', 'tec', null, 'Ao receber uma prescrição de 2 comprimidos de 25 mg de captopril, havendo na unidade apenas comprimidos de 50 mg, o técnico deve:', '["administrar 1 comprimido de 50 mg, pois corresponde à dose total prescrita de 50 mg, após conferência com o enfermeiro.","administrar 2 comprimidos de 50 mg.","administrar meio comprimido de 50 mg.","não administrar e não comunicar ninguém.","administrar 4 comprimidos de 50 mg."]'::jsonb, 0, 'Dose prescrita: 2 × 25 mg = 50 mg = 1 comprimido de 50 mg. A conferência evita erros de interpretação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-315', 'tec', null, 'Foram prescritos 0,25 mg de digoxina por via oral. Há comprimidos de 0,125 mg. Deve-se administrar:', '["2 comprimidos.","1/2 comprimido.","1 comprimido.","4 comprimidos.","3 comprimidos."]'::jsonb, 0, '0,25 ÷ 0,125 = 2 comprimidos. Antes de administrar a digoxina, verifica-se a frequência cardíaca.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-316', 'tec', null, 'Prescrição: 3 mg de midazolam EV. Disponível: ampola de 15 mg/3 mL. O volume a ser aspirado é de:', '["0,6 mL.","1 mL.","3 mL.","0,3 mL.","1,5 mL."]'::jsonb, 0, '15 mg — 3 mL (5 mg/mL); 3 mg — x → x = 0,6 mL.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-317', 'tec', null, 'Prescrição: 75 mg de tramadol EV. Disponível: ampola de 100 mg/2 mL. O volume a ser aspirado é de:', '["1,5 mL.","0,75 mL.","2 mL.","1 mL.","1,25 mL."]'::jsonb, 0, '100 mg — 2 mL; 75 mg — x → x = 1,5 mL.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-318', 'tec', null, 'Prescrição: 40 mg de omeprazol EV. Frasco-ampola de 40 mg com diluente de 10 mL. Após a reconstituição, o volume total a ser administrado, para a dose prescrita, é de:', '["10 mL.","5 mL.","40 mL.","4 mL.","1 mL."]'::jsonb, 0, 'A dose prescrita corresponde ao frasco inteiro: 40 mg em 10 mL.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-319', 'tec', null, 'Prescrição: 2 mg de morfina EV. Disponível: ampola de 10 mg/mL, que foi diluída em 9 mL de água destilada (volume final de 10 mL). O volume a ser administrado é de:', '["2 mL.","0,2 mL.","1 mL.","5 mL.","10 mL."]'::jsonb, 0, 'Após diluição: 10 mg em 10 mL = 1 mg/mL; para 2 mg, administra-se 2 mL.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-320', 'tec', null, 'Prescrição: 500 mg de metronidazol EV. Disponível: bolsa de 100 mL com 5 mg/mL. Deve-se administrar:', '["100 mL (a bolsa inteira).","50 mL.","5 mL.","10 mL.","500 mL."]'::jsonb, 0, '5 mg/mL × 100 mL = 500 mg.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-321', 'tec', null, 'Prescrição: 1 g de dipirona EV. Ampola disponível: 500 mg/mL, com 2 mL. Deve-se aspirar:', '["2 mL.","1 mL.","0,5 mL.","4 mL.","5 mL."]'::jsonb, 0, '500 mg — 1 mL; 1.000 mg — x → x = 2 mL.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-322', 'tec', null, 'Foram prescritas 10 UI de insulina regular SC. A unidade dispõe de frasco de 100 UI/mL e de seringa de insulina de 100 UI. O técnico deve:', '["aspirar até a marca de 10 UI na seringa de insulina.","aspirar 1 mL.","aspirar 10 mL.","aspirar 0,01 mL em seringa de 3 mL.","aspirar até a marca de 100 UI."]'::jsonb, 0, 'A seringa de insulina já é graduada em unidades: basta aspirar até 10 UI (equivalente a 0,1 mL).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-323', 'tec', null, 'Um paciente apresenta prescrição de 100 mL de soro fisiológico para correr em 30 minutos, com equipo microgotas. O gotejamento será de:', '["200 microgotas/min.","100 microgotas/min.","67 microgotas/min.","50 microgotas/min.","300 microgotas/min."]'::jsonb, 0, 'Microgotas/min = (V × 60) ÷ minutos = (100 × 60) ÷ 30 = 200. Na prática, prefere-se bomba de infusão para vazões elevadas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-324', 'tec', null, 'Sobre a administração de medicamentos por via intramuscular, registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-325', 'tec', null, 'No preparo de medicamentos, a conferência da prescrição, do rótulo e do paciente deve ocorrer:', '["no momento da separação, no preparo e antes da administração, à beira do leito.","apenas no momento da separação na farmácia.","somente após a administração.","apenas quando o medicamento é novo para o paciente.","uma vez por plantão, de forma geral."]'::jsonb, 0, 'A conferência em vários momentos reduz erros de medicação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-326', 'tec', null, 'Ao administrar um medicamento por via oral, o técnico deve:', '["permanecer junto ao paciente até que ele ingira o medicamento, oferecendo água, quando permitido.","deixar o medicamento sobre a mesa de cabeceira para o paciente tomar depois.","entregar o medicamento ao acompanhante sem orientação.","triturar todos os comprimidos, sem exceção.","administrar com o paciente deitado em decúbito dorsal horizontal."]'::jsonb, 0, 'Deixar o medicamento sem supervisão impede a confirmação da administração; o paciente deve estar sentado ou com a cabeceira elevada.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-327', 'tec', null, 'Na cadeia de sobrevivência da parada cardiorrespiratória extra-hospitalar no adulto, os primeiros elos são:', '["reconhecimento da PCR e acionamento do serviço de emergência, seguidos de RCP de alta qualidade imediata e desfibrilação rápida.","administração de adrenalina e intubação orotraqueal.","transporte imediato ao hospital, sem compressões.","verificação da glicemia e da pressão arterial.","aguardar a chegada da equipe médica antes de qualquer intervenção."]'::jsonb, 0, 'O reconhecimento precoce, a RCP imediata e a desfibrilação rápida são os elos que mais aumentam a sobrevida.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-328', 'tec', null, 'Ao encontrar uma vítima adulta caída, após verificar a segurança da cena, o profissional de saúde deve checar a responsividade e, simultaneamente, avaliar a respiração e o pulso carotídeo em, no máximo:', '["10 segundos.","30 segundos.","1 minuto.","3 segundos.","2 minutos."]'::jsonb, 0, 'Se a vítima não responde, não respira (ou apresenta gasping) e não tem pulso, iniciam-se as compressões imediatamente.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-329', 'tec', null, 'Durante uma RCP em suporte básico de vida, o DEA analisa o ritmo e indica "choque não recomendado". A conduta imediata da equipe é:', '["reiniciar imediatamente as compressões torácicas de alta qualidade, mantendo a relação 30:2 até nova análise.","aplicar adrenalina e amiodarona.","mudar a posição das pás e analisar novamente.","checar o pulso por 30 segundos antes de qualquer conduta.","interromper a RCP e aguardar o médico."]'::jsonb, 0, 'Após a análise, retomam-se as compressões; o DEA reanalisa o ritmo a cada 2 minutos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-330', 'tec', null, 'Na RCP de alta qualidade, as interrupções das compressões torácicas, por exemplo para análise do ritmo ou ventilação, devem ser:', '["minimizadas, com pausas inferiores a 10 segundos.","de 30 segundos, para descanso do socorrista.","realizadas a cada 30 compressões, por 1 minuto.","evitadas apenas no primeiro minuto.","irrelevantes para a sobrevida."]'::jsonb, 0, 'Pausas longas reduzem a perfusão coronariana e cerebral; o revezamento de quem comprime deve ocorrer a cada 2 minutos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-331', 'tec', null, 'Nas compressões torácicas em adulto, as mãos do socorrista devem ser posicionadas:', '["no centro do tórax, sobre a metade inferior do esterno.","sobre o apêndice xifoide.","sobre o hemitórax esquerdo, na região do mamilo.","no terço superior do esterno, próximo à fúrcula.","sobre o abdome superior."]'::jsonb, 0, 'Comprimir o apêndice xifoide pode causar lesões de órgãos abdominais.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-332', 'tec', null, 'Durante a RCP com via aérea avançada instalada (por exemplo, tubo orotraqueal), a ventilação deve ser realizada:', '["a cada 6 segundos (10 ventilações por minuto), sem interromper as compressões contínuas.","na relação 30:2, com pausas para ventilar.","a cada 2 segundos, para melhorar a oxigenação.","somente após cada ciclo de 2 minutos.","apenas quando houver retorno da circulação espontânea."]'::jsonb, 0, 'A hiperventilação aumenta a pressão intratorácica e reduz o retorno venoso.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
